//! Pure-Rust escrow vault state machine.
//!
//! This crate is the dependency-free logic core of the escrow vault.
//! It models the full lifecycle of a two-party escrow with initializer
//! authority checks and amount invariants. The Anchor program under
//! `programs/escrow-vault` wraps exactly this logic for the Solana target.

mod events;
mod keeper;
mod snapshot;
// AV-74: deterministic indexer-event CSV export (RFC 4180, zero
// dependencies) — `events_to_csv` / `csv_to_events`, the
// data-analysis / audit-ingest complement to the AV-26 snapshot JSON.
mod event_csv;
mod cpi;
// AV-35: CPI-routed release — third-party program invocation modeled as
// data, validated before settlement, with an injected executor seam and
// rollback on executor failure (mirrors on-chain CPI atomicity).
mod cpi_call;
// AV-32: Anchor account discriminators + panic-free vault account decoding
// (production code: indexers and keeper tooling verify on-chain bytes).
mod discriminator;
// AV-33: batch settlement execution plan over the keeper report.
mod execution_plan;
// AV-37: batch lifecycle scan — one report with the executable
// `initialize -> fund -> release` call list for many escrows, ALT
// support, and per-item failure isolation (fleet bring-up / sweep).
mod batch;
// AV-79: batch vault close — dual-party bound, filtered,
// failure-isolated `close_vaults` over many vaults (AV-34 gates per
// vault) with a per-item report and Σ rent-exempt reclaim via the
// `vault_close_rent_reclaimed` main formula; the indexed variant emits
// one `VaultClosed` per closed vault plus a single `VaultsBatchClosed`
// summary. Off-chain execution only — no new on-chain instruction.
mod batch_close;
// AV-61: keeper execution bundles — pack the batch lifecycle scan's
// (AV-37) executable actions into `(mint, caller)` signing-session
// bundles with real instruction discriminators, logical accounts, and
// ALT tables, as deterministic multisig/CLI-ready JSON. Purely
// additive and read-only (dry-run by construction).
mod execution_bundle;
// AV-71: signable transaction-message serialization — turn an execution
// bundle's actions into real Solana legacy transaction messages
// (discriminator + Borsh params + logical account metas, base64) that a
// multisig/CLI can sign and submit. Off-chain and unsigned by design:
// the relay never holds keys. Purely additive.
mod tx_message;
// AV-88: compute-unit budget estimation for keeper execution plans —
// heuristic per-instruction CU costs (single source of truth table),
// batch aggregation, and over-limit warnings against the per-transaction
// compute budget. Pure logic, zero dependencies.
mod cu_estimate;
// AV-89: priority-fee oracle — keeper-side recent-prioritization-fees
// EWMA estimator (configurable window/decay, micro-lamports/CU
// recommendation + confidence, conservative flagged fallback), the
// AV-88 fee-budget combination (`fee_budget_lamports`), and the
// compute-budget instruction data assembly the bundle dry-run report
// passes through (see `tx_message`). Pure logic, zero dependencies.
mod priority_fee;
// AV-92: deterministic vault PDA derivation — hand-rolled Solana
// `create_program_address` / `find_program_address` (SHA-256 hash
// layout over the crate's `sha256`, ed25519 off-curve bump search
// over hand-written field arithmetic), zero dependencies. Seeds are
// recorded off-chain on the watch structs; the scans attach the
// derived vault address to their reports. Purely additive.
mod pda;
// AV-72: escrow configuration templates — one-call constructors for the
// four canonical escrow compositions (auction, milestone-plan,
// subscription, arbitrated-dispute) with template-level combination
// validation. Client-side composition only: produces a plain `Escrow`,
// so the vault layout, IDL, and Anchor program are untouched.
mod templates;
// AV-78: escrow aggregate statistics view — read-only fleet rollup
// (per-state counts, amount histogram, escrow durations, locked totals)
// for keeper/operator dashboards, with deterministic JSON export.
mod aggregate;
// AV-94: event-sourced materialized fund view — fold an EscrowEvent
// stream into the per-escrow (locked, released, refunded) triple plus
// the fleet aggregate for keeper/indexer consumption, with strict seq
// continuity (`GapInEventStream`) and snapshot-base + incremental
// apply. Pure logic, zero dependencies.
mod event_sourcing;
#[cfg(test)]
mod idl_json;
#[cfg(test)]
mod sim;
mod multisig;

// ---------------------------------------------------------------------------
// SHA-256 (hand-rolled, zero dependencies).
// ---------------------------------------------------------------------------

/// SHA-256 over `message`, FIPS 180-4. Crate-level primitive shared by
/// the Anchor discriminator constructors (`account:` / `global:`
/// namespaces, AV-32) and the test-only IDL pipeline (AV-29). The
/// crate stays dependency-free, so the implementation lives here
/// instead of an external crate.
pub(crate) fn sha256(message: &[u8]) -> [u8; 32] {
    #[rustfmt::skip]
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ];
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];
    let mut padded = message.to_vec();
    let bit_len = (message.len() as u64).wrapping_mul(8);
    padded.push(0x80);
    while padded.len() % 64 != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in padded.chunks_exact(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[4 * i], chunk[4 * i + 1], chunk[4 * i + 2], chunk[4 * i + 3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let (mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh) =
            (h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ (!e & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }
    let mut out = [0u8; 32];
    for (i, word) in h.iter().enumerate() {
        out[4 * i..4 * i + 4].copy_from_slice(&word.to_be_bytes());
    }
    out
}

