    fn funded_escrow() -> Escrow {
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT).unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    fn quorum_funded_escrow() -> Escrow {
        let policy = QuorumPolicy::new(&[ATTESTOR_1, ATTESTOR_2], &[1, 1], 2).unwrap();
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_quorum(policy)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    fn quorum_3_of_3_funded_escrow() -> Escrow {
        let policy = QuorumPolicy::new(&[ATTESTOR_1, ATTESTOR_2, ATTESTOR_3], &[1, 1, 1], 3).unwrap();
        let mut e = Escrow::initialize(ALICE, BOB, 1_000_000, EXPIRES_AT)
            .unwrap()
            .with_quorum(policy)
            .unwrap();
        e.fund(ALICE, EXPIRES_AT - 3_600).unwrap();
        e
    }

    // ----- the consistency check -----

    #[test]
    fn instruction_set_is_complete() {
        // The public transition API of the state machine. If you add a
        // transition, add its instruction spec to INSTRUCTIONS and extend
        // this list — this test fails until you do.
        const TRANSITIONS: &[&str] = &[
            "Escrow::initialize",
            "Escrow::fund",
            "Escrow::release",
            "Escrow::release_split",
            "Escrow::release_via_cpi",
            "Escrow::cancel",
            "Escrow::cancel_expired",
            "Escrow::cancel_partial",
            "Escrow::crank_expired",
            "QuorumPolicy::new + Escrow::with_quorum",
            "Escrow::update_quorum",
            "Escrow::update_attestors",
            "Escrow::with_dual_sig",
            "Escrow::activate",
            "VestingSchedule::new/new_with_cliff + Escrow::with_vesting/with_vesting_cliff",
            "Escrow::claim",
            "Escrow::attest",
            "Escrow::with_arbiter",
            "Escrow::escalate",
            "Escrow::resolve",
            "MilestonePlan::new + Escrow::with_milestones",
            "Escrow::confirm_milestone",
            "Escrow::release_milestone",
            "Escrow::skip_milestone",
            // AV-70: milestone tranche re-split by dual-signed
            // governance (before any settlement).
            "Escrow::adjust_milestone_amounts",
            // AV-73: subscription per-period re-split by dual-signed
            // governance (released periods locked).
            "Escrow::adjust_period_amounts",
            "Escrow::with_mint",
            "Escrow::with_protocol_fee",
            "Escrow::with_grace_period",
            "Escrow::with_refund_address",
            "Escrow::with_penalty_bps",
            "Escrow::with_timelock",
            "Escrow::with_decimals",
            "Escrow::with_fee_recipient",
            "Escrow::with_emergency_unlock",
            "Escrow::emergency_unlock",
            "Escrow::close_vault",
            "Escrow::release_and_close",
            "Escrow::with_pause_authority",
            "Escrow::pause",
            "Escrow::unpause",
            "Escrow::rotate_pause_authority",
            "Escrow::rotate_taker",
            "Escrow::rotate_initializer",
            "Escrow::rotate_arbiter",
            // AV-67: protocol-fee recipient rotation by dual-signed
            // governance.
            "Escrow::rotate_fee_recipient",
            // AV-65: arbiter-panel multisig judgment.
            "Escrow::with_arbiter_panel",
            "Escrow::submit_panel_judgment",
            "Escrow::with_payout_allowlist",
            "Escrow::update_payout_allowlist",
            // AV-96: payout destination denylist — the compliance veto,
            // orthogonal to the AV-49 allowlist, deny taking precedence.
            "Escrow::with_denylist",
            "Escrow::update_payout_denylist",
            // AV-83: CPI target-program allowlist.
            "Escrow::with_cpi_allowlist",
            "Escrow::update_cpi_allowlist",
            "Escrow::with_reference",
            "Escrow::with_arbitration_deadline",
            "Escrow::confirm_default_judgment",
            "Escrow::trigger_default_judgment",
            // AV-56: periodic (subscription-style) release schedule.
            "Escrow::with_subscription",
            "Escrow::release_period",
            "Escrow::with_max_extension_secs",
            "Escrow::extend_expiry",
            // AV-63: absolute protocol-fee ceiling.
            "Escrow::with_fee_cap",
            // AV-66: tiered protocol-fee schedule.
            "Escrow::with_fee_schedule",
            // AV-64: relative timelock (fund-anchored unlock).
            "Escrow::with_relative_timelock",
            // AV-68: dispute-evidence disclosure deadline + disclosure.
            "Escrow::with_evidence_deadline",
            "Escrow::submit_evidence",
            // AV-69: panel threshold governance.
            "Escrow::update_panel_threshold",
            // AV-75: one-step schema migration by initializer governance.
            "Escrow::migrate_schema",
            // AV-81: dual-signed funded-escrow split into N child escrows.
            "Escrow::split_escrow",
            // AV-82: opt-in default-penalty (slash) terms + enforcement.
            "Escrow::with_slash_terms",
            "Escrow::slash",
            // AV-86: opt-in slash-appeal window + taker filing + panel
            // review.
            "Escrow::with_appeal_window",
            "Escrow::file_appeal",
            "Escrow::review_appeal",
            // AV-84: opt-in multisig authority binding.
            "Escrow::with_multisig_authority",
            // AV-90: opt-in non-linear vesting unlock curve.
            "VestingCurve::stepped + Escrow::with_vesting_curve",
            // AV-91: per-document evidence disclosure against the
            // committed Merkle root.
            "Escrow::file_evidence",
            // AV-95b: per-leg basket settlement — one leg (one SPL
            // mint) settled per call; the basket owns its settlement
            // path.
            "Escrow::initialize_basket",
            "Escrow::release_basket",
            "Escrow::cancel_basket",
            "Escrow::cancel_expired_basket",
            // AV-95c: atomic all-legs basket settlement — every
            // unsettled leg settles in one transition, any leg failure
            // rolls the whole settlement back.
            "Escrow::release_basket_all",
            "Escrow::cancel_basket_all",
            // AV-97: opt-in Dutch-auction settlement — the descending
            // price curve the taker's `claim` prices through while the
            // window is live.
            "Escrow::with_dutch_auction",
        ];
        assert_eq!(
            INSTRUCTIONS.len(),
            TRANSITIONS.len(),
            "instruction count drifted from transition count"
        );
        for t in TRANSITIONS {
            assert!(
                INSTRUCTIONS.iter().any(|s| s.method == *t),
                "no instruction spec covers transition {t}"
            );
        }
        let mut seen = HashSet::new();
        for s in INSTRUCTIONS {
            assert!(
                seen.insert(s.method),
                "duplicate instruction spec for {}",
                s.method
            );
        }
    }

